mapper.select:
select

from PBC_PROD_ASSETPOOL_CODE
where INSIDE_PROD_ID = #{insideProdId}
and CODE_TYPE = #{codeType}
and STATUS = #{status}

mapper.delete:
delete from PBC_PROD_ASSETPOOL_CODE
where INSIDE_PROD_ID = #{insideProdId,jdbcType=VARCHAR}
  and CODE_TYPE = #{codeType,jdbcType=VARCHAR}

mapper.select:
SELECT insideProdId, max(pbcProjectCodeExternal) pbcProjectCodeExternal, max(pbcAssetPoolCodeExternal) pbcAssetPoolCodeExternal, max(pbcProjectCodeSystem) pbcProjectCodeSystem, max(pbcAssetPoolCodeSystem) pbcAssetPoolCodeSystem FROM (select t1.INSIDE_PROD_ID as insideProdId, (case t1.CODE_TYPE when #{codeTypeProduct} then t1.PBC_CODE else null end) as pbcProjectCodeExternal, (case t1.CODE_TYPE when #{codeTypeAssets} then t1.PBC_CODE else null end) as pbcAssetPoolCodeExternal, t2.PBC_PROD_ID as pbcProjectCodeSystem, t3.PBC_ACCOUNT_ID as pbcAssetPoolCodeSystem, case t1.CODE_TYPE when #{codeTypeProduct} then '产品' when #{codeTypeAssets} then '资产' else null end as codeTypeName, t1.CODE_TYPE as codeType, t1.PBC_CODE as pbcCode from PBC_PROD_ASSETPOOL_CODE t1 left join PBC_PRD_BASEINFO_SUB t2 on t1.INSIDE_PROD_ID = t2.PROD_ID and t1.CODE_TYPE =#{codeTypeProduct} left join PBC_PRD_ACCOUNT_SUB t3 on t1.INSIDE_PROD_ID=t3.ACCOUNT_ID and t1.CODE_TYPE =#{codeTypeAssets} where t1.STATUS =#{statusEffective}
and t1.INSIDE_PROD_ID in
#{insideProdId}
and t2.PBC_PROD_ID=#{pbcProjectCode}
and t3.PBC_ACCOUNT_ID=#{pbcAssetPoolCode} ) s group by insideProdId

select
t1.INSIDE_PROD_ID as insideProdId,
case t1.CODE_TYPE when #{codeTypeProduct} then '产品'
when #{codeTypeAssets}  then '资产'
else null
end as codeTypeName,
t1.CODE_TYPE as codeType,
t1.PBC_CODE as pbcCode
from
PBC_PROD_ASSETPOOL_CODE t1
where
t1.STATUS =#{statusEffective}

    and t1.INSIDE_PROD_ID in

        #{insideProdId}



    and t1.PBC_CODE=#{pbcProjectCode}


    and t1.PBC_CODE=#{pbcAssetPoolCode}



        #{key,jdbcType=VARCHAR}


order by t1.UPDATE_TIME desc
